\begin{tikzpicture}[line cap=round,line join=round,>=stealth,scale=1.0]
% concave mirror close to a small object (tooth)
\draw[thick] (0,1.4) .. controls (1.0,0.4) and (1.0,-0.4) .. (0,-1.4);
\foreach \y in {-1.2,-0.8,-0.4,0,0.4,0.8,1.2} {\draw[thin] (-0.05,\y)--++(-0.25,0);}
\node[font=\small] at (0.2,1.75) {concave mirror};
% small object close to mirror
\draw[thick,fill=gray!20] (1.35,-0.25) rectangle (1.65,0.25);
\node[font=\footnotesize] at (1.5,-0.55) {tooth};
% enlarged erect image sketched farther left of viewer? show dashed larger tooth near mirror face
\draw[dashed,thick] (0.55,-0.55) rectangle (1.05,0.55);
\node[font=\footnotesize] at (0.8,0.8) {enlarged image};
\draw[->,thick] (1.5,0.35)--(0.95,0.45);
\end{tikzpicture}
